  "<b>Alliées cette semaine</b> : Infernal et Nécrotique<br>{e0}": "<b>Allied this week</b>: Infernal and Necrotic<br>{e0}",
  "<b>Annonces</b> : les grosses attaques des gardiens et des élites s’affichent sur la frise, à côté de leur portrait. Brise-les avant qu’ils jouent pour les annuler.": "<b>Announcements</b>: the big attacks of guardians and elites appear on the turn bar, next to their portrait. Break them before they act to cancel them.",
  "<b>Artificiel · Verrou artificiel</b>{e0}": "<b>Artificial · Artificial Lock</b>{e0}",
  "<b>Assaut conjoint</b> ({0} Ferveur, une fois par combat) : sur un ennemi Fêlé, Brisé ou Marqué, ta créature et celle qui joue juste après frappent ensemble (×{1} chacune), avec l’effet de leurs deux rôles. L’alliée appelée perd son tour à venir. C’est aussi un coup de rupture.": "<b>Joint Assault</b> ({0} Fervor, once per battle): on a Cracked, Broken or Marked enemy, your creature and the one acting right after strike together (×{1} each), with the effects of both their roles. The called ally loses its upcoming turn. It's also a breaking blow.",
  "<b>Assaut conjoint</b>{e0}": "<b>Joint Assault</b>{e0}",
  "<b>Attaque</b> (gratuite, +{0} PA) : dégâts fiables, +{1} Ferveur. <b>Défense</b> (gratuite, +{2} PA) : -{3} % de dégâts jusqu’à son prochain tour. <b>Passer</b> : elle ne fait rien. <b>Permuter</b> (une fois par tour) : une créature de la réserve prend sa place et joue tout de suite ; PV, PA et états sont gardés, et la réserve récupère {4} % de PV par tour. En entrant, elle déclenche un petit effet lié à son rôle (bouclier, soin, Ferveur, ralentissement…).": "<b>Attack</b> (free, +{0} AP): reliable damage, +{1} Fervor. <b>Defend</b> (free, +{2} AP): -{3}% damage until its next turn. <b>Pass</b>: it does nothing. <b>Swap</b> (once per turn): a creature from the reserve takes its place and acts right away; HP, AP and statuses are kept, and the reserve recovers {4}% HP per turn. On entering, it triggers a small effect tied to its role (shield, heal, Fervor, slow…).",
  "<b>Bien miser</b>{e0}": "<b>Bidding well</b>{e0}",
  "<b>Booster de l’Abysse</b>{e0}": "<b>Abyss Booster</b>{e0}",
  "<b>Booster gratuit du jour</b><small>Il se garde : jusqu’à {0} en réserve si tu ne l’ouvres pas tout de suite.</small>": "<b>Free daily booster</b><small>It keeps: up to {0} in reserve if you don’t open it right away.</small>",
  "<b>Booster premium</b>{e0}": "<b>Premium Booster</b>{e0}",
  "<b>Booster standard</b>{e0}": "<b>Standard Booster</b>{e0}",
  "<b>Brisure</b> : en visant une élite ou un gardien, la cible affiche la Brisure que ton coup va infliger (◆), et « BRISE ! » quand il va le briser. Un seul coup ne retire jamais plus de {0} % des PV d’un gardien.": "<b>Break</b>: when targeting an elite or a guardian, the target shows the Break your hit will deal (◆), and “BREAKS!” when it will Break it. A single hit never removes more than {0}% of a guardian's HP.",
  "<b>Butin gagné</b>{e0}": "<b>Loot won</b>{e0}",
  "<b>Butin</b>{e0}": "<b>Loot</b>{e0}",
  "<b>Capturer</b>{e0}": "<b>Capturing</b>{e0}",
  "<b>Carapace de Métatron</b> : Se donne un bouclier, donne un bouclier à l’allié choisi et se soigne de {0} %.": "<b>Métatron's Carapace</b>: Gains a shield, gives a shield to the chosen ally and heals itself for {0}%.",
  "<b>Cartes échangées</b>{e0}": "<b>Cards swapped</b>{e0}",
  "<b>Chacun son tour</b> : toutes les créatures, les tiennes et les ennemies, jouent <b>une fois par tour</b>, dans l’ordre de leur vitesse (frise de portraits en haut de l’écran). Chaque carte a son <b>attaque</b> (épée) et ses <b>PV</b> (cœur).<br><br>Quand vient le tour d’une de tes créatures, ses actions s’ouvrent : choisis sa première action (son attaque), puis l’ennemi. Chaque créature a ses propres <b>PA</b> (losanges verts) : l’attaque en rapporte {0}, les compétences en coûtent.<br><br><b>Appui long</b> sur une carte : sa fiche (PV, attaque, intention).": "<b>Take turns</b>: every creature, yours and the enemy’s, acts <b>once per turn</b>, in order of speed (the portrait strip at the top of the screen). Each card has its <b>attack</b> (sword) and its <b>HP</b> (heart).<br><br>When it’s one of your creatures’ turn, its actions open up: choose its first action (its attack), then the enemy. Each creature has its own <b>AP</b> (green diamonds): attacking earns {0}, skills cost some.<br><br><b>Long press</b> a card: its sheet (HP, attack, intent).",
  "<b>Chacun son tour</b> : toutes les créatures, les tiennes et les ennemies, jouent une fois par tour, dans l’ordre de leur vitesse. L’ordre s’affiche en haut de l’écran ; « T{0} » marque le début du tour suivant. Quand c’est le tour d’une de tes créatures, ses actions s’ouvrent : choisis l’action, puis la cible. Raccourci : touche un ennemi pour l’attaquer.": "<b>Taking turns</b>: every creature, yours and the enemy's, acts once per turn, in order of speed. The order is shown at the top of the screen; “T{0}” marks the start of the next turn. When it's one of your creatures' turn, its actions open up: choose the action, then the target. Shortcut: tap an enemy to attack it.",
  "<b>Chaque attaque ennemie se défend.</b> Le geste dépend de l’attaque :<br><br><b>Coup simple</b> : une barre apparaît, le curseur file vers la droite. <b>Touche</b> quand il passe dans la <b>zone dorée</b> : esquive (ta créature est seulement <b>éraflée</b>, +{0} Ferveur). Sur le <b>trait blanc</b> au bout de la zone : <b>parade parfaite</b>, aucun dégât, +{1} PA, +{2} Ferveur, +{3} Brisure à l’attaquant, et contre-attaque des Protecteurs et Attaquants.<br><br><b>Coup chargé</b> : <b>garde le doigt appuyé</b>, puis <b>relâche</b> dans l’or (ou sur le trait blanc).<br><br><b>Attaque de zone</b> : une flèche apparaît. <b>Glisse ton doigt</b> dans son sens : vite (partie blanche du minuteur), toute l’équipe est à l’abri ; plus tard, elle est éraflée.<br><br>Un coup non défendu frappe <b>fort</b> : c’est ta défense qui garde tes créatures en vie.": "<b>Every enemy attack can be defended.</b> The gesture depends on the attack:<br><br><b>Basic strike</b>: a bar appears and the cursor races to the right. <b>Tap</b> when it passes through the <b>golden zone</b>: dodge (your creature is only <b>grazed</b>, +{0} Fervor). On the <b>white line</b> at the end of the zone: <b>perfect parry</b>, no damage, +{1} AP, +{2} Fervor, +{3} Break to the attacker, and a counterattack from Protectors and Strikers.<br><br><b>Charged Strike</b>: <b>hold your finger down</b>, then <b>release</b> in the gold (or on the white line).<br><br><b>Area attack</b>: an arrow appears. <b>Swipe your finger</b> in its direction: quickly (white part of the timer), the whole team is sheltered; later, it’s grazed.<br><br>An undefended strike hits <b>hard</b>: your defense is what keeps your creatures alive.",
  "<b>Coffre de la semaine</b>{e0}{e1}": "<b>Weekly Chest</b>{e0}{e1}",
