  "<b>Défense active</b> (toutes les attaques ennemies) : coup simple, touche dans l’or pour esquiver (ta créature est éraflée, +{0} Ferveur), sur le trait blanc, au tout dernier instant, pour parer (aucun dégât, +{1} PA, +{2} Ferveur, Brisure, contre-attaque des Protecteurs et des Attaquants) ; coup chargé, garde le doigt appuyé et relâche au bon moment ; attaque de zone, glisse ton doigt dans le sens de la flèche.": "<b>Active defense</b> (all enemy attacks): basic strike, tap in the gold to dodge (your creature is grazed, +{0} Fervor), on the white line, at the very last moment, to parry (no damage, +{1} AP, +{2} Fervor, Break, counterattack from Protectors and Strikers); Charged Strike, hold your finger and release at the right moment; area attack, swipe your finger in the direction of the arrow.",
  "<b>Défense active</b>{e0}": "<b>Active defense</b>{e0}",
  "<b>Défi du jour</b>{e0} {e1}": "<b>Daily challenge</b>{e0} {e1}",
  "<b>Dés</b> : Coup d’estoc, Contagion et Entrave lancent un D{0} contre une difficulté (DD). {1} : échec critique ; sous le DD : réussite partielle ; DD atteint : réussite ; {2} : critique. Marque, gel, Brisure et faiblesse donnent des bonus.": "<b>Dice</b>: Thrust, Contagion and Shackle roll a D{0} against a difficulty (DC). {1}: critical failure; below the DC: partial success; DC reached: success; {2}: critical. Mark, frost, Break and weakness give bonuses.",
  "<b>Détonation</b> : un ennemi à {0} poisons ou plus explose sous un Raz-de-marée (poison × {1} de dégâts d’un coup).": "<b>Detonation</b>: an enemy with {0} or more poison stacks explodes under a Tidal Wave (poison × {1} damage at once).",
