  "<b>En entrant</b> : L’ennemi qui visait la créature remplacée est ralenti : sa prochaine attaque fait moitié moins mal.": "<b>On entry</b>: The enemy targeting the replaced creature is slowed: its next attack deals half damage.",
  "<b>Enchaînement</b> : chaque créature qui frappe un ennemi déjà touché ce tour-ci par une autre de tes créatures gagne +{0} dégât (+{1} au plus). Le « +{2} » doré sur la cible l’annonce.": "<b>Chaining</b>: each creature that hits an enemy already hit this turn by another of your creatures gains +{0} damage (+{1} max). The golden “+{2}” on the target shows it.",
  "<b>Ennemis à mécanique</b>{e0}": "<b>Enemies with mechanics</b>{e0}",
  "<b>Entrave glaciale</b><small>Maintiens le doigt pour charger le dé, relâche dans l’or, au centre pour un parfait</small>": "<b>Glacial Shackle</b><small>Hold to charge the die, release in the gold, dead center for a perfect</small>",
  "<b>Entrée en scène</b>{e0}": "<b>Entrance</b>{e0}",
  "<b>Faiblesse</b> : inconnue. Frappe-la avec la bonne faction, ou marque-la, pour la découvrir.": "<b>Weakness</b>: unknown. Hit it with the right faction, or Mark it, to discover it.",
  "<b>Faiblesses</b> : chaque faction en craint une autre (+{0} % de dégâts) ; contre sa propre faction : -{1} %. ★ sur une cible = faiblesse exploitée.": "<b>Weaknesses</b>: each faction fears another (+{0}% damage); against its own faction: -{1}%. ★ on a target = weakness exploited.",
  "<b>Fin du tour</b>": "<b>End of turn</b>",
  "<b>Forme endormie</b>{e0}": "<b>Dormant form</b>{e0}",
  "<b>Fêlure et Brisure</b> (élites, gardiens) : jauge vide, l’ennemi est <b>Fêlé</b>. Un <b>coup de rupture</b> (attaque d’un Protecteur, Coup d’estoc, Raz-de-marée, ou coup qui consomme une Marque) le <b>brise</b> : son attaque annoncée est annulée, il perd sa prochaine action, subit +{0} % de dégâts et +{1} aux jets contre lui jusqu’à la fin du tour suivant. Sans rupture avant la fin du tour suivant, il se ressaisit (jauge à moitié).": "<b>Crack and Break</b> (elites, guardians): when the gauge is empty, the enemy is <b>Cracked</b>. A <b>breaking blow</b> (a Protector's attack, Thrust, Tidal Wave, or a hit that consumes a Mark) <b>Breaks</b> it: its announced attack is canceled, it loses its next action, takes +{0}% damage and +{1} to rolls against it until the end of the next turn. Without a breaking blow before the end of the next turn, it recovers (gauge at half).",
