  "Accumule le poison, puis Contagion pour le propager.": "Stack poison, then use Contagion to spread it.",
  "Accumule {0} poisons ou plus, puis Raz-de-marée : le poison explose (× {1} en dégâts d’un coup).": "Stack {0} or more poison, then Tidal Wave: the poison explodes (× {1} as instant damage).",
  "Acheter": "Buy",
  "Acheter {e0}": "Buy {e0}",
  "Acheter · {0}": "Buy · {0}",
  "Acheter · {0} €": "Buy · €{0}",
  "Achetée une fois, la finition se pose sur autant de cartes que tu veux, depuis la fiche de chaque carte. Elle ne change rien à leurs valeurs.": "Bought once, the finish can be applied to as many cards as you like, from each card's page. It doesn't change their stats.",
  "Achète des boosters avec tes <b>éclats</b>, ou ouvre ceux qu’on t’offre : un <b>booster gratuit chaque jour</b> (il se garde : jusqu’à {0} en réserve si tu manques un jour). Déchire le paquet du doigt, puis retourne les cartes.<br><br>Une carte peut sortir dans une <b>finition rare</b> : <b>argentée</b> (gravée à la pointe d’argent), <b>enluminée</b> (une page dorée du Bestiaire) ou <b>abyssale</b> (envahie par l’encre de l’Abysse, la plus rare). Tu peux aussi <b>sublimer</b> une carte que tu possèdes vers la finition suivante, contre des cendres (Collection → Forge → Fournaise, ou fiche de la carte, onglet Rareté).": "Buy boosters with your <b>shards</b>, or open the ones you’re given: a <b>free booster every day</b> (it keeps: up to {0} in reserve if you miss a day). Tear the pack open with your finger, then flip the cards.<br><br>A card can come in a <b>rare finish</b>: <b>Silvered</b> (engraved in silverpoint), <b>Illuminated</b> (a gilded page of the Bestiary) or <b>Abyssal</b> (overrun by the ink of the Abyss, the rarest). You can also <b>exalt</b> a card you own to the next finish, for ashes (Collection → Forge → Furnace, or the card’s sheet, Rarity tab).",
  "Achève les cibles empoisonnées, et son poison passe à un voisin (Éveil).": "Finishes off Poisoned targets, and her poison spreads to a neighbor (Awakening).",
  "Achève {0} ennemis avec elle": "Finish off {0} enemies with it",
  "Achève-le d’un coup, ou gèle-le.": "Finish it in one blow, or freeze it.",
