  "Brise-la ou gèle-la pendant que la ruche s’éveille, esquive l’Essaim, et purifie le poison (Prière).": "Break or freeze her while the hive awakens, dodge the Swarm, and cleanse the poison (Prayer).",
  "Brise-le ou gèle-le pendant qu’il remonte le temps, ou garde tes plus gros coups pour juste après.": "Break or freeze him while he rewinds time, or save your biggest hits for right after.",
  "Brise-le pendant le Chant, esquive la Complainte et dépense ta Ferveur avant qu’elle ne tombe. Une Brisure retient la marée un tour.": "Break it during the Chant, dodge the Lament and spend your Fervor before it drops. A Break holds back the tide for one turn.",
