  "Brûle des cartes pour des cendres. Les cendres font monter tes créatures de niveau (Forge → Renforcer).": "Burn cards for Ashes. Ashes level up your creatures (Forge → Empower).",
  "Brûle des cartes pour obtenir des <b>cendres</b>. <b>Tout brûler</b> ne prend que tes doublons : tu gardes toujours un exemplaire de chaque finition.<br><br>Plus la carte est rare, plus elle donne de cendres, et les finitions rares bien plus encore. Tu peux aussi brûler ta dernière copie, après confirmation.": "Burn cards to get <b>ashes</b>. <b>Burn all</b> only takes your duplicates: you always keep one copy of each finish.<br><br>The rarer the card, the more ashes it gives, and rare finishes far more. You can also burn your last copy, after confirming.",
  "Brûle tes doublons dans la Fournaise pour gagner des cendres.": "Burn your duplicates in the Furnace to earn Ashes.",
