  "Ce chapitre n’est pas encore ouvert : bats d’abord le gardien qui le précède.": "This chapter isn't open yet: first beat the guardian before it.",
  "Ce compte a déjà une partie en ligne.": "This account already has an online save.",
  "Ce compte n’est pas encore confirmé.": "This account isn't confirmed yet.",
  "Ce gardien est protégé par <b>trois runes</b> (pastille en haut) : chacune retire <b>{0} %</b> des dégâts qu’il subit.<br><br>Chaque rune cède à une action précise (Brisure, Marque, parade parfaite, faiblesse, poison lourd, Assaut conjoint, serviteurs abattus) : <b>touche la pastille</b> pour savoir lesquelles. Les trois brisées, il est <b>Fêlé</b>. Ses serviteurs debout renforcent sa grosse attaque.": "This guardian is protected by <b>three runes</b> (badge at the top): each one removes <b>{0}%</b> of the damage it takes.<br><br>Each rune gives way to a specific action (Break, Mark, perfect parry, weakness, heavy poison, Joint Assault, minions slain): <b>tap the badge</b> to see which. Once all three are broken, it is <b>Cracked</b>. Its standing minions strengthen its big attack.",
  "Ce joueur n’est pas (ou plus) ton ami.": "This player is not (or no longer) your friend.",
  "Ce lien a expiré : demande-en un nouveau.": "This link has expired: request a new one.",
  "Ce nom est déjà connu.": "This name is already known.",
  "Ce n’est pas encore son tour : regarde l’ordre des tours, en haut de l’écran.": "It's not its turn yet: check the turn order at the top of the screen.",
  "Ce n’est pas ton tour.": "It's not your turn.",
  "Ce pseudo est déjà pris.": "This username is already taken.",
  "Ce pseudo n’est pas accepté. Choisis-en un autre.": "This username isn't allowed. Pick another one.",
  "Ce pseudo te semble choquant, haineux ou trompeur ? Signale-le : au bout de plusieurs signalements, il est masqué pour tout le monde. Ton signalement est anonyme pour ce joueur.": "Does this username seem offensive, hateful or misleading? Report it: after several reports, it’s hidden for everyone. Your report is anonymous to this player.",
  "Ce que l’adversaire avait retenu ne vaut plus rien.": "What your opponent had memorized is now worthless.",
  "Ce qui attend au fond": "What waits at the bottom",
  "Ce qui coule ne remonte pas.": "What sinks never rises.",
  "Ce qui deviendra démon · Commune": "What will become a demon · Common",
  "Ce qui est construit obéit. Jusqu’au jour où.": "What is built obeys. Until the day it doesn’t.",
  "Ce qui existait avant les sept royaumes, et ce qui existera après.": "What existed before the seven realms, and what will exist after.",
  "Ce qui reste des cartes brûlées dans la Fournaise. Elles font monter le niveau de tes créatures et permettent de sublimer une carte vers une finition plus rare.": "What's left of cards burned in the Furnace. They level up your creatures and let you Exalt a card to a rarer finish.",
  "Ce sont les marins d’une flotte entière, engloutie en une nuit. Ils ont chanté jusqu’au fond, et l’Abysse a trouvé leur chant trop beau pour le laisser s’éteindre.": "They are the sailors of an entire fleet, swallowed in a single night. They sang all the way to the bottom, and the Abyss found their song too beautiful to let it die.",
  "Ce texte n’est pas un code de sauvegarde ABYSSAL.": "This text is not an ABYSSAL save code.",
