  "Compte chaque carte sortie, sans jamais se tromper.": "Counts every card played, never making a mistake.",
  "Compte confirmé : tu es connecté, ta partie sera sauvegardée en ligne.": "Account confirmed: you're signed in, and your progress will be saved online.",
  "Compte créé ! Un e-mail de confirmation t’a été envoyé : touche son lien, puis reviens te connecter ici.": "Account created! A confirmation email has been sent to you: tap its link, then come back here to sign in.",
  "Compte créé : ta partie est maintenant sauvegardée en ligne.": "Account created: your game is now saved online.",
  "Compte créé et connecté : ta partie en ligne est chargée.": "Account created and signed in: your online game is loaded.",
  "Compte les cartes déjà tirées, pèse chaque risque, se presse quand tu approches du but.": "Counts the cards already drawn, weighs every risk, hurries when you near the goal.",
  "Compte les lots qui restent, avec des écarts difficiles à prévoir.": "Counts the lots left, with swings that are hard to predict.",
  "Compte les lots qui restent, et bluffe parfois.": "Counts the lots left, and sometimes bluffs.",
  "Compte supprimé.": "Account deleted.",
