  "Concentration": "Focus",
  "Concentration…": "Focusing…",
  "Concentre son énergie, puis frappe toute ton équipe.": "Focuses its energy, then strikes your whole team.",
  "Concentre tes coups sur l’élite ou le gardien pour le briser : il perd son tour.": "Focus your strikes on the elite or guardian to break it: it loses its turn.",
  "Condamne ta créature la plus affaiblie : il l’exécutera au tour suivant. Permute-la en réserve, défends-la, ou brise-le.": "Condemns your weakest creature: he will execute it next turn. Swap it to the reserve, defend it, or break him.",
  "Condamnée": "Condemned",
  "Condamnée : le Bourreau l’exécutera à son prochain tour (permute-la en réserve pour l’épargner)": "Condemned: the Executioner will execute it on his next turn (swap it to the reserve to spare it)",
