  "Coup de rupture": "Breaking Blow",
  "Coup de rupture. Frappe tous les ennemis au combat ({0} % de son attaque), +{1} Brisure à chacun, et consomme toutes les Marques. Un ennemi à {2} poisons ou plus détone (poison × {3}).": "Breaking blow. Strikes all enemies in combat ({0}% of its attack), +{1} Break to each, and consumes all Marks. An enemy with {2} or more poison detonates (poison × {3}).",
