  "Crypte mouvante : chaque fois que la main passe, deux cartes face cachée échangent leur place, sous tes yeux.": "Shifting crypt: each time the turn passes, two face-down cards swap places, before your eyes.",
  "Crypte mouvante et deux paires maudites.": "Shifting crypt and two cursed pairs.",
  "Cryptes à venir ({0})": "Upcoming crypts ({0})",
  "Créateur": "Creator",
  "Créatures": "Creatures",
  "Créatures affichées": "Creatures shown",
