  "Désigne ta créature la plus affaiblie : pendant {0} tours, tous les ennemis la visent et lui font +{1} % de dégâts. Mets-la en réserve ou protège-la.": "Marks your weakest creature: for {0} turns, all enemies target it and deal +{1}% damage to it. Move it to the reserve or protect it.",
