  "Effroi": "Dread",
  "Elle a déjà joué ce tour.": "It has already played this turn.",
  "Elle a exaucé tous les vœux des Scelleurs : la gloire, la puissance, l’oubli. Le prix, c’était l’Abysse. Elle attend encore qu’ils finissent de payer.": "She granted every wish of the Sealers: glory, power, oblivion. The price was the Abyss. She is still waiting for them to finish paying.",
  "Elle a gelé son propre royaume pour qu’il ne change plus jamais. Quand l’Abysse a voulu l’emporter, elle s’est offerte à lui en échange d’un hiver sans fin. On dit qu’elle pleure encore, mais que ses larmes gèlent avant de tomber.": "She froze her own kingdom so it would never change again. When the Abyss came to take it, she offered herself in exchange for an endless winter. They say she still weeps, but her tears freeze before they fall.",
  "Elle a passé sa vie à se regarder vieillir. Un jour, elle a refusé, et son reflet a pris sa place. Personne ne sait laquelle des deux est sortie du miroir.": "She spent her life watching herself grow old. One day she refused, and her reflection took her place. No one knows which of the two stepped out of the mirror.",
  "Elle annonce « La ruche s’éveille », puis lâche son Essaim au tour suivant : toute ton équipe est frappée et empoisonnée. Plus tes créatures sont empoisonnées, plus elle se régénère.": "She announces “The hive awakens,” then unleashes her Swarm the next turn: your whole team is hit and poisoned. The more of your creatures are poisoned, the more she regenerates.",
  "Elle combattra sous sa forme originelle.": "It will fight in its original form.",
  "Elle comptera comme perdue pour aujourd’hui.": "It will count as lost for today.",
  "Elle cède quand il porte {0} poisons ou plus.": "It gives way when it carries {0} or more poison.",
  "Elle cède quand le gardien est brisé.": "It gives way when the guardian is broken.",
  "Elle cède quand on exploite sa faiblesse de faction.": "It gives way when its faction weakness is exploited.",
  "Elle cède quand tous ses serviteurs sont tombés.": "It gives way when all its servants have fallen.",
  "Elle cède quand une Marque est consommée sur lui.": "It gives way when a Mark is consumed on it.",
  "Elle cède sous un Assaut conjoint.": "It gives way to a Joint Assault.",
  "Elle cède sur une parade parfaite contre lui.": "It gives way on a perfect parry against it.",
  "Elle dresse un Miroir : le prochain coup que tu lui portes se retourne contre ton attaquant ({0} % des dégâts), puis le miroir se brise.": "She raises a Mirror: the next hit you land on her turns against your attacker ({0}% of the damage), then the mirror shatters.",
  "Elle dresse un Miroir un tour sur deux.": "She raises a Mirror every other turn.",
  "Elle empoisonne sans relâche, et à chaque tour le poison saute d’une créature empoisonnée à ses voisines saines (deux fois plus en phase {0}). Tous les trois tours, elle prépare une vague sur toute ton équipe.": "She poisons relentlessly, and every turn the poison leaps from a poisoned creature to its healthy neighbors (twice as much in phase {0}). Every three turns, she prepares a wave on your whole team.",
  "Elle entre avec un bouclier qui bloque le prochain coup.": "It enters with a shield that blocks the next hit.",
  "Elle exauce un Vœu : tu gagnes {0} Ferveur et tes créatures {1} PA. Au tour suivant, elle réclame son Prix : un coup sur toute ton équipe, qui la soigne de la moitié des dégâts.": "She grants a Wish: you gain {0} Fervor and your creatures {1} AP. The next turn, she claims her Price: a hit on your whole team that heals her for half the damage.",
  "Elle garde désormais le vide": "She now guards the void",
  "Elle grandit : +{0} ATQ et {1} % de ses PV max en plus, un tour sur deux (à chaque tour en phase {2}). Plus le combat dure, plus elle est terrible. Une Brisure la fait rétrécir.": "It grows: +{0} ATK and {1}% more max HP, every other turn (every turn in phase {2}). The longer the fight lasts, the more terrible it becomes. A Break makes it shrink.",
  "Elle grandit : {0} ATQ": "It grows: {0} ATK",
  "Elle grandit à chaque tour, et non plus un tour sur deux.": "It grows every turn, no longer every other turn.",
  "Elle n’a jamais été seule : chacune de ses filles porte un morceau de sa mémoire. Quand les Scelleurs ont muré sa ruche, elle a simplement appris à pondre dans la pierre.": "She was never alone: each of her daughters carries a piece of her memory. When the Sealers walled up her hive, she simply learned to lay her eggs in stone.",
  "Elle n’a ni corps ni nom. Elle était une maladie, puis une prière murmurée par ceux qu’elle emportait, et l’Abysse a fini par lui donner un visage.": "She has neither body nor name. She was a disease, then a prayer whispered by those she carried away, and the Abyss ended up giving her a face.",
  "Elle n’est pas au combat.": "It's not in combat.",
  "Elle rassemble le froid pendant un tour, puis déchaîne une Tempête de givre sur toute ton équipe et gèle ta créature la plus forte (deux en phase {0}).": "She gathers the cold for one turn, then unleashes a Frost Storm on your whole team and freezes your strongest creature (two in phase {0}).",
  "Elle redevient insaisissable à chaque tour où elle n’attaque pas.": "She becomes elusive again each turn she doesn't attack.",
  "Elle reviendra demain, avec de nouveaux ennemis.": "It’ll be back tomorrow, with new enemies.",
  "Elle se défend déjà.": "It's already defending.",
  "Elle se révèle en combat.": "It reveals itself in combat.",
  "Elle te rend chaque coup": "She returns every blow",
  "Elle vaut pour la Descente et les Épreuves d’aujourd’hui.": "It applies to today's Descent and Trials.",
  "Elle vient d’être gelée : immunisée au gel ce tour-ci.": "It was just frozen: immune to freezing this turn.",
  "Elle voyage de souffle en souffle": "She travels from breath to breath",
