  "En haut du combat, un <b>objectif</b> facultatif (cible dorée) : sans perte, en peu de tours, une parade, une Brisure… Touche-le pour le lire.<br><br>Réussi et combat gagné : des <b>éclats</b> en plus et <b>+{0} Ferveur</b> pour la suite du chapitre. Manqué : rien de perdu.": "At the top of the combat, an optional <b>objective</b> (golden target): no losses, few turns, a parry, a Break… Tap it to read it.<br><br>Completed and combat won: extra <b>shards</b> and <b>+{0} Fervor</b> for the rest of the chapter. Missed: nothing lost.",
