  "Frappe la cible et un ennemi voisin, chacun à {0} % de son attaque.": "Hits the target and an adjacent enemy, each for {0}% of its attack.",
  "Frappe la condamnée avec deux fois sa force (trois fois si elle a perdu la moitié de ses PV). Si elle tombe, il gagne +{0} ATQ.": "Strikes the condemned with twice his strength (three times if it has lost half its HP). If it falls, he gains +{0} ATK.",
  "Frappe la même cible avec plusieurs créatures : chaque coup suivant gagne un bonus d’Enchaînement.": "Hit the same target with several creatures: each following strike gains a Chain bonus.",
  "Frappe n’importe quel ennemi, même derrière un Protecteur : dégâts normaux et +{0} poison.": "Strikes any enemy, even behind a Protector: normal damage and +{0} poison.",
  "Frappe parfaite": "Perfect strike",
  "Frappe parfaite : réussite assurée": "Perfect strike: guaranteed success",
  "Frappe plus fort quand il perd des PV (+{0} % sous la moitié).": "Hits harder as it loses HP (+{0}% below half).",
  "Frappe plusieurs ennemis à la fois.": "Hits several enemies at once.",
  "Frappe rythmée": "Rhythmic strike",
  "Frappe ta créature la plus forte et l’enchaîne : elle ne pourra pas agir à ton prochain tour.": "Strikes your strongest creature and chains it: it can't act on your next turn.",
  "Frappe tous les ennemis au combat, plus fort à chaque tour.": "Strikes every enemy in battle, harder each turn.",
  "Frappe toute la ligne ennemie.": "Hits the whole enemy line.",
  "Frappe toute ton équipe et empoisonne chaque créature (+{0} poison, +{1} en phase {2}).": "Strikes your whole team and poisons every creature (+{0} poison, +{1} in phase {2}).",
  "Frappe toute ton équipe et empoisonne chaque créature (+{0} poison, +{1} en phase {2}). Renforcée par ses serviteurs : +{3} %.": "Strikes your whole team and poisons each creature (+{0} poison, +{1} in phase {2}). Boosted by its minions: +{3}%.",
  "Frappe toute ton équipe et gèle ta créature la plus forte (deux en phase {0}).": "Strikes your whole team and freezes your strongest creature (two in phase {0}).",
  "Frappe toute ton équipe et la soigne de la moitié des dégâts.": "Strikes your whole team and heals her for half the damage.",
  "Frappe toute ton équipe, retire ses boucliers et ses bonus d’attaque, et te fait perdre {0} Ferveur.": "Strikes your whole team, strips its shields and attack bonuses, and makes you lose {0} Fervor.",
  "Frappe toutes tes créatures au combat.": "Strikes all your creatures in battle.",
  "Frappe toutes tes créatures au combat. Renforcée par ses serviteurs : +{0} %.": "Strikes all your creatures in battle. Boosted by its minions: +{0}%.",
  "Frappe vite et fort : garde ta Ferveur pour un pouvoir d’équipe tôt, et brise-la dès que possible.": "Strike fast and hard: save your Fervor for an early team power, and break it as soon as possible.",
  "Frappe à {0} % ; la cible est ralentie (sa prochaine attaque fait moitié moins mal) et reçoit {1} poison.": "Strikes at {0}%; the target is slowed (its next attack deals half damage) and takes {1} poison.",
  "Frapper une cible marquée ou brisée rapporte +{0} Ferveur (une fois par tour).": "Hitting a Marked or Broken target grants +{0} Fervor (once per turn).",
