  "Loup de l’Abîme": "Wolf of the Deep",
  "Lucifer : en réserve, {0} PV sur {1}": "Lucifer: in reserve, {0} of {1} HP",
  "Lucifer : {0}/{1} PV": "Lucifer: {0}/{1} HP",
  "Lucifer, Mythique, Abyssale": "Lucifer, Mythic, Abyssal",
  "Lucifer, l’Étoile du Matin : au combat, {0} PV sur {1}": "Lucifer, l’Étoile du Matin: in battle, {0} of {1} HP",
