  "Merci, ton signalement a été envoyé. Ce joueur est masqué pour toi.": "Thank you, your report was sent. This player is hidden for you.",
  "Merci. Ce pseudo est maintenant masqué pour tout le monde.": "Thank you. This username is now hidden for everyone.",
  "Mes prières ont été mal placées.": "My prayers were misplaced.",
  "Mes équipes": "My teams",
  "Messagères du Seigneur · Commune": "Messengers of the Lord · Common",
  "Mettre en pause": "Pause",
  "Mettre en réserve": "Move to reserve",
  "Meute brisée": "Broken pack",
  "Mi-chemin. Les aiguilles des horloges reculent quand tu avances. Le gardien de ce chapitre a volé du temps aux Scelleurs, assez pour les voir vieillir et mourir. Il en a encore en réserve, et il compte bien s’en servir.": "Halfway. The clock hands turn back as you move forward. This chapter's guardian stole time from the Sealers, enough to watch them grow old and die. He still has some in reserve, and he fully intends to use it.",
  "Miasme abyssal": "Abyssal Miasma",
  "Miasme ardent": "Burning Miasma",
  "Miasme sauvage": "Wild Miasma",
  "Mille visages": "Thousand faces",
