  "Miroir : le prochain coup qu’elle reçoit se retourne contre l’attaquant ({0} %). Le poison passe à travers.": "Mirror: the next hit it takes is turned back on the attacker ({0}%). Poison goes through.",
  "Miroir de l’Abîme": "Mirror of the Deep",
