  "Sceau : il protège d’une brisure. Gardien : arrêt forcé, tu encaisses tout de suite. Offrande : la prochaine carte compte double.": "Seal: protects you from a break. Guardian: forced stop, you bank right away. Offering: the next card counts double.",
  "Sceau de la Mort incarnée": "Seal of Death Incarnate",
  "Sceau de l’Ange aux Mille Yeux": "Seal of the Thousand-Eyed Angel",
  "Sceau du Roi Sans Tombe": "Seal of the Tombless King",
  "Sceau du Serment": "Seal of the Oath",
  "Sceau funèbre": "Funereal Seal",
  "Score copié : colle-le dans un message.": "Score copied: paste it into a message.",
