  "Vaincre la Matriarche du Givre": "Defeat the Frost Matriarch",
  "Vaincre le Dévoreur": "Defeat the Devourer",
  "Vaincs L’Abysse, le gardien de l’étage {0} de la Descente.": "Defeat The Abyss, the guardian of floor {0} of the Descent.",
  "Vaincs ce gardien dans la Descente.": "Defeat this guardian in the Descent.",
  "Vaincs ton <b>premier gardien</b> dans la Descente (étage {0}) pour ouvrir la Salle des jeux.": "Defeat your <b>first guardian</b> in the Descent (floor {0}) to open the Game Room.",
  "Vaincs ton <b>premier gardien</b> dans la Descente (étage {0}) pour ouvrir la salle des ventes.": "Defeat your <b>first guardian</b> in the Descent (floor {0}) to open the auction room.",
  "Vaincs ton <b>premier gardien</b> dans la Descente (étage {0}) pour ouvrir les Duels des Sceaux.": "Defeat your <b>first guardian</b> in the Descent (floor {0}) to open the Seal Duels.",
