  "Vendu une seule fois. Le cadre et le dos de cartes du Fondateur, le titre « Fondateur » (badge au classement) et {0} obsidiennes.": "Sold only once. The Founder's frame and card back, the “Founder” title (Leaderboard badge) and {0} Obsidians.",
